self.FRX=self.FRX||{};(FRX.gx=FRX.gx||{})["fr"]={"etre-present":["Être : le verbe de l'identité","\"être\" sert à dire qui on est, d'où on vient, son métier et à décrire : \"je suis\", \"tu es\", \"il est\", \"nous sommes\", \"vous êtes\", \"ils sont\". Apprenez-le par cœur : c'est le verbe le plus fréquent du français. Exemples : \"je suis\", \"nous sommes\", \"ils sont\""],"avoir-present":["Avoir : la possession","\"avoir\" exprime la possession : \"j'ai\", \"tu as\", \"il a\", \"nous avons\", \"vous avez\", \"ils ont\". Il sert aussi à former le passé composé. Attention à l'élision \"j'ai\" devant un son voyelle. Exemples : \"j'ai\", \"elle a\", \"nous avons\""],"il-y-a":["Il y a : l'existence","\"il y a\" présente ce qui existe, au singulier comme au pluriel, et ne change jamais : \"il y a un livre\", \"il y a des livres\". Négation : \"il n'y a pas de livre\". La question : \"y a-t-il\" ou \"est-ce qu'il y a\". Exemples : \"il y a un café\", \"il n'y a pas de lait\""],"art-defini":["Les articles définis","\"le\" (masculin), \"la\" (féminin), \"l'\" (devant une voyelle) et \"les\" (pluriel) désignent une chose connue. On les emploie aussi pour les idées générales : \"j'aime la musique\" signifie qu'on aime la musique en général. Exemples : \"le café\", \"la pomme\", \"les enfants\""],"art-indefini":["Les articles indéfinis","\"un\" (masculin), \"une\" (féminin) et \"des\" (pluriel) présentent quelque chose de nouveau ou de non précisé : \"j'ai un frère et des cousins\". Au pluriel, \"des\" est obligatoire. Exemples : \"un frère\", \"une sœur\", \"des amis\""],"gender-nouns":["Masculin ou féminin ?","Tout nom est masculin ou féminin. Les terminaisons aident : \"-tion\", \"-té\", \"-ette\" sont le plus souvent féminines ; \"-ment\", \"-age\", \"-eau\" le plus souvent masculines. Apprenez toujours le nom avec son article : \"la ville\", \"le village\". Exemples : \"le village\", \"la ville\", \"la question\""],"plural-regular":["Le pluriel en -s","La plupart des noms prennent \"-s\" au pluriel, qu'on n'entend pas : \"un ami\", \"des amis\". Les noms en \"-s\", \"-x\" ou \"-z\" ne changent pas : \"un pays\", \"des pays\". Seuls l'article et la liaison montrent le pluriel à l'oral. Exemples : \"deux sœurs\", \"trois amis\""],"plural-irregular":["Les pluriels irréguliers","Les noms en \"-al\" font \"-aux\" : \"un journal\", \"des journaux\". Les noms en \"-eau\" et \"-eu\" prennent \"-x\" : \"un bateau\", \"des bateaux\", \"un jeu\", \"des jeux\". Il y a quelques exceptions, comme \"un festival, des festivals\". Exemples : \"des journaux\", \"des bateaux\", \"des cheveux\""],"elision-basic":["L'élision devant une voyelle","Les petits mots \"le\", \"la\", \"je\", \"ne\", \"de\", \"que\", \"se\" perdent leur voyelle devant une voyelle ou un h muet et prennent une apostrophe : \"l'école\", \"j'aime\", \"n'aime pas\", \"qu'elle\". \"les\" et \"un\" ne s'élident jamais. Exemples : \"l'école\", \"j'aime\", \"qu'elle\""],"contractions-au-du":["au, aux, du, des","\"à + le\" devient \"au\", \"à + les\" devient \"aux\", \"de + le\" devient \"du\", \"de + les\" devient \"des\". Avec \"la\" et \"l'\", rien ne change : \"à la gare\", \"de la gare\". On n'écrit jamais \"à le\" ni \"de le\". Exemples : \"au marché\", \"aux voisins\", \"du professeur\""],"partitif":["Le partitif : une partie de","Pour parler d'une quantité de quelque chose qu'on ne compte pas, on emploie \"du\" (masculin), \"de la\" (féminin), \"de l'\" (voyelle) ou \"des\" (pluriel) : \"je prends du café\". Le partitif est toujours nécessaire en français. Exemples : \"du pain\", \"de la salade\", \"des légumes\""],"de-negation":["La négation + de","Après \"ne… pas\", \"jamais\", \"plus\", l'article indéfini ou partitif devient \"de\" : \"j'ai un chat\" devient \"je n'ai pas de chat\". Exception : après \"être\", on garde l'article : \"ce n'est pas un chat\". Exemples : \"pas de voiture\", \"jamais de viande\""],"adj-agreement":["L'accord de l'adjectif","L'adjectif s'accorde avec le nom : \"-e\" au féminin et \"-s\" au pluriel. \"grand\", \"grande\", \"grands\", \"grandes\". Ceux qui finissent par -e ne changent pas au féminin : \"un garçon sympa\", \"une fille sympa\". Exemples : \"elle est grande\", \"ils sont petits\""],"adj-position":["Où place-t-on l'adjectif ?","La plupart des adjectifs se placent après le nom : \"une robe bleue\". Quelques adjectifs courts se placent avant : beauté, âge, bonté, taille (\"beau, jeune, bon, grand, petit\") : \"un petit chien\". \"beau\" a les formes \"bel\" et \"belle\". Exemples : \"une belle maison\", \"une maison blanche\""],"possessifs":["Les possessifs : mon, ma, mes","Le possessif s'accorde avec la chose possédée, pas avec le possesseur : \"mon père\", \"ma mère\", \"mes parents\". Devant une voyelle, les noms féminins prennent \"mon\" : \"mon amie\". Aussi : \"notre/nos\", \"votre/vos\", \"leur/leurs\". Exemples : \"mon père\", \"ma mère\", \"leurs chats\""],"demonstratifs":["Ce, cette, ces","\"ce\" (masculin), \"cet\" (masculin devant une voyelle), \"cette\" (féminin) et \"ces\" (pluriel) montrent une personne ou une chose. On ajoute \"-ci\" ou \"-là\" pour comparer : \"ce livre-ci\", \"ce livre-là\". Exemples : \"ce livre\", \"cette veste\", \"ces enfants\""],"pres-er":["Présent : verbes en -er","On enlève \"-er\" et on ajoute \"-e, -es, -e, -ons, -ez, -ent\" : \"parler\" donne \"je parle\", \"tu parles\", \"il parle\", \"nous parlons\", \"vous parlez\", \"ils parlent\". Environ 90 % des verbes français suivent ce modèle. Exemples : \"je parle\", \"nous parlons\", \"ils parlent\""],"pres-ir-re":["Présent : verbes en -ir et -re","Les verbes réguliers en \"-ir\" prennent \"-is, -is, -it, -issons, -issez, -issent\" : \"finir\", \"je finis\", \"nous finissons\". Les verbes en \"-re\" prennent \"-s, -s, -, -ons, -ez, -ent\" : \"vendre\", \"je vends\", \"il vend\". Exemples : \"je finis\", \"nous finissons\", \"je vends\""],"pres-irreguliers":["Les verbes irréguliers courants","Apprenez \"aller\" (\"je vais, nous allons\"), \"faire\" (\"je fais, vous faites\"), \"prendre\" (\"je prends, ils prennent\") et \"venir\" (\"je viens, ils viennent\"). Attention à \"vous faites\" et \"ils font\" : ils sortent du modèle. Exemples : \"je vais\", \"nous faisons\", \"ils prennent\", \"vous venez\""],"tu-vous":["Tu ou vous ?","On dit \"tu\" aux amis, à la famille, aux enfants et aux personnes de son âge. On dit \"vous\" aux inconnus, aux personnes plus âgées, dans les magasins, au travail, et toujours quand on parle à plusieurs personnes. En cas de doute, commencez par \"vous\". Exemples : \"tu viens\", \"vous venez\""],"on-nous":["On = nous","Dans le français de tous les jours, \"on\" remplace \"nous\", mais le verbe reste à la troisième personne du singulier : \"on va au cinéma\". \"On\" veut aussi dire « les gens en général » : \"en France, on mange du pain\". Exemples : \"on va\", \"on mange\""],"neg-ne-pas":["La négation : ne … pas","On place \"ne\" avant le verbe et \"pas\" après : \"je ne parle pas\". Devant une voyelle, \"ne\" devient \"n'\" : \"il n'aime pas\". À l'oral, on supprime souvent \"ne\", mais à l'écrit on le garde. Exemples : \"je ne parle pas\", \"il n'aime pas\""],"q-est-ce-que":["Poser une question oui/non","Le plus simple : garder l'ordre des mots et monter la voix, ou écrire un point d'interrogation : \"tu viens ?\". Plus formel : on place \"est-ce que\" devant : \"est-ce que tu viens ?\". Devant une voyelle, on écrit \"est-ce qu'\" : \"est-ce qu'elle vient ?\". Exemples : \"tu aimes le thé ?\", \"est-ce que vous avez\""],"q-mots-interrogatifs":["Les mots interrogatifs","\"où\" (le lieu), \"quand\" (le moment), \"comment\" (la manière), \"combien\" (la quantité), \"pourquoi\" (la cause), \"qui\" (la personne). Ils se placent au début : \"où est la gare ?\". On répond à \"pourquoi\" par \"parce que\". Exemples : \"où\", \"quand\", \"combien\", \"pourquoi\""],"q-quel":["Quel : l'adjectif interrogatif","\"quel\" s'accorde avec le nom : \"quel\" (m. sing.), \"quelle\" (f. sing.), \"quels\" (m. pl.), \"quelles\" (f. pl.). Il peut suivre le nom après \"être\" : \"quel est ton nom ?\" Exemples : \"quelle heure\", \"quels films\""],"futur-proche":["Le futur proche : aller + infinitif","On conjugue \"aller\" au présent et on ajoute un infinitif : \"je vais travailler\", \"nous allons manger\". Négation : \"je ne vais pas partir\". C'est la façon la plus courante de parler de ses projets à l'oral. Exemples : \"je vais manger\", \"elle va partir\""],"pres-pronominaux":["Les verbes pronominaux","Ces verbes ont un pronom qui correspond au sujet : \"je me\", \"tu te\", \"il se\", \"nous nous\", \"vous vous\", \"ils se\". Exemples : \"se lever\", \"se coucher\", \"s'habiller\". Négation : \"je ne me lève pas\". Exemples : \"je me lève\", \"elle se couche\""],"imperatif-present":["L'impératif","On emploie les formes du présent de \"tu\", \"nous\", \"vous\" sans le pronom : \"tu parles\" donne \"parle !\", \"nous parlons\" donne \"parlons !\", \"vous parlez\" donne \"parlez !\". Les verbes en \"-er\" perdent le -s final à la forme \"tu\". Irréguliers : \"sois, soyons, soyez\", \"aie, ayons, ayez\". Exemples : \"parle !\", \"parlons !\", \"parlez !\""],"modaux-pouvoir-vouloir":["vouloir, pouvoir, devoir","Ces trois verbes sont suivis d'un infinitif : \"je veux manger\", \"tu peux venir\", \"nous devons partir\". Ils sont irréguliers : \"je veux, nous voulons\", \"je peux, nous pouvons\", \"je dois, nous devons\". Exemples : \"je veux partir\", \"tu peux\", \"nous devons\""],"prep-lieu":["Dire où est quelque chose","Mots de lieu courants : \"dans\", \"sur\", \"sous\", \"devant\", \"derrière\", \"entre\", \"à côté de\", \"près de\". Après \"de\", pensez aux contractions : \"à côté du parc\". Exemples : \"sur la table\", \"sous la table\", \"entre la poste et la banque\""],"prep-a-chez-de":["à, chez, de","\"à\" s'emploie avec les villes et les lieux : \"je vais à Lyon\". \"chez\" s'emploie avec une personne, sa maison ou son magasin : \"chez le dentiste\", \"chez moi\". \"de\" indique l'origine : \"je viens de Lyon\". Exemples : \"chez Marie\", \"à Lyon\", \"de la gare\""],"nombres":["Les nombres","Formes particulières : \"soixante-dix\" (70), \"quatre-vingts\" (80, avec un -s), \"quatre-vingt-dix\" (90). \"et\" apparaît dans 21, 31, 41, 51, 61 et 71, mais pas dans 81 et 91. Les traits d'union relient les dizaines et les unités. Exemples : \"vingt et un\", \"soixante-dix\", \"quatre-vingts\""],"heure-date":["L'heure et la date","On dit \"il est\" + l'heure : \"il est trois heures et quart\". \"midi\" et \"minuit\" prennent \"et demi\", les autres heures \"et demie\". Dates : \"le 5 mai\" ; seul le premier jour est ordinal : \"le premier mai\". L'heure se construit avec \"à\" : \"à neuf heures\". Exemples : \"huit heures et demie\", \"le cinq mai\""],"c-est-ce-sont":["C'est, ce sont","On emploie \"c'est\" + nom singulier et \"ce sont\" + nom pluriel pour présenter ou identifier : \"c'est un livre\", \"ce sont des livres\". À l'oral, \"c'est\" s'emploie souvent aussi avec un pluriel. Question : \"qu'est-ce que c'est ?\" Exemples : \"c'est mon frère\", \"ce sont mes amis\""],"gouts-aimer":["Les goûts","Après \"aimer\", \"adorer\", \"détester\" et \"préférer\", on emploie l'article défini, pas le partitif : \"j'aime le café\", \"elle adore les chats\". On peut ajouter \"beaucoup\" : \"j'aime beaucoup la musique\". Exemples : \"j'aime le chocolat\", \"je déteste les épinards\""],"adv-intensite":["Dire l'intensité","\"très\" se place devant un adjectif ou un adverbe : \"très bien\". \"beaucoup\" se place après le verbe : \"il travaille beaucoup\". Devant un nom, on dit \"beaucoup de\" : \"beaucoup de fruits\". \"un peu\" et \"trop\" fonctionnent comme \"beaucoup\". Exemples : \"très grand\", \"il mange beaucoup\", \"un peu\""],"avoir-expressions":["Expressions avec avoir","On emploie \"avoir\", et non \"être\", pour l'âge et pour beaucoup de sensations : \"j'ai vingt ans\", \"j'ai faim\", \"j'ai soif\", \"j'ai chaud\", \"j'ai froid\", \"j'ai peur\", \"j'ai sommeil\". On peut ajouter \"très\" : \"j'ai très faim\". Exemples : \"j'ai faim\", \"elle a vingt ans\", \"il a froid\""],"clause-et-mais-parce-que":["Les mots de liaison","\"et\" ajoute, \"ou\" propose un choix, \"mais\" oppose, \"parce que\" donne une raison. Devant une voyelle, \"parce que\" devient \"parce qu'\" : \"parce qu'il pleut\". \"donc\" annonce la conséquence. Exemples : \"et\", \"mais\", \"parce que\""],"pc-avoir":["Le passé composé avec avoir","La plupart des verbes forment le passé avec \"avoir\" au présent + le participe passé : \"j'ai mangé\", \"tu as fini\", \"il a vendu\". Participes : \"-er\" donne \"-é\", \"-ir\" donne \"-i\", \"-re\" donne \"-u\". Exemples : \"j'ai mangé\", \"nous avons fini\""],"pc-etre":["Le passé composé avec être","Une quinzaine de verbes se conjuguent avec \"être\" : \"aller, venir, arriver, partir, entrer, sortir, monter, descendre, rester, tomber, naître, mourir, retourner, passer\" et tous les verbes pronominaux. Pour les retenir, on utilise la liste appelée \"DR MRS VANDERTRAMP\". Exemples : \"je suis allé\", \"elle est partie\""],"pc-accord-etre":["L'accord du participe avec être","Avec \"être\", le participe s'accorde avec le sujet : \"-e\" au féminin et \"-s\" au pluriel. \"il est parti\", \"elle est partie\", \"ils sont partis\", \"elles sont parties\". Exemples : \"elle est partie\", \"ils sont venus\", \"elles sont allées\""],"pc-pronominaux":["Les pronominaux au passé","Les verbes pronominaux se conjuguent avec \"être\", et le pronom se place avant : \"je me suis levé\", \"elle s'est couchée\", \"ils se sont promenés\". Le participe s'accorde en général avec le sujet. Exemples : \"je me suis levé\", \"elle s'est couchée\""],"pc-negation":["Le passé composé négatif","On place \"ne … pas\" autour de l'auxiliaire, pas autour du participe : \"je n'ai pas mangé\", \"elle n'est pas venue\". C'est pareil avec \"jamais\", \"plus\", \"rien\" : \"il n'a rien dit\". Exemples : \"je n'ai pas mangé\", \"il n'est jamais venu\""],"pc-participes-irreguliers":["Les participes irréguliers","Formes à connaître : \"avoir\" donne \"eu\", \"être\" donne \"été\", \"faire\" donne \"fait\", \"prendre\" donne \"pris\", \"voir\" donne \"vu\", \"dire\" donne \"dit\", \"écrire\" donne \"écrit\", \"mettre\" donne \"mis\", \"pouvoir\" donne \"pu\", \"vouloir\" donne \"voulu\". Exemples : \"j'ai eu\", \"j'ai été\", \"il a fait\", \"elle a pris\""],"imparfait-formation":["L'imparfait : la formation","On prend la forme \"nous\" du présent, on enlève \"-ons\" et on ajoute \"-ais, -ais, -ait, -ions, -iez, -aient\" : \"nous parlons\" donne \"je parlais\". Seul \"être\" est irrégulier : \"j'étais, nous étions\". Exemples : \"je jouais\", \"nous allions\", \"il était\""],"imparfait-usage":["L'imparfait : quand l'employer","On emploie l'\"imparfait\" pour le décor d'une histoire : la météo, les sentiments, les descriptions et les habitudes. \"Il faisait beau\", \"j'étais fatigué\", \"chaque été, nous allions à la mer\". Exemples : \"il faisait beau\", \"je jouais\", \"nous habitions\""],"impf-vs-pc":["Imparfait ou passé composé ?","\"Imparfait\" : ce qui était en cours, le décor. \"Passé composé\" : ce qui s'est passé, un événement qui fait avancer l'histoire. \"Je lisais quand le téléphone a sonné\" : la lecture était en cours, la sonnerie l'a interrompue. Exemples : \"je dormais\", \"le téléphone a sonné\""],"futur-simple":["Le futur simple","On part de l'infinitif (on enlève le -e final des verbes en \"-re\") et on ajoute \"-ai, -as, -a, -ons, -ez, -ont\" : \"parler\" donne \"je parlerai\", \"prendre\" donne \"je prendrai\". Exemples : \"je parlerai\", \"nous prendrons\", \"ils finiront\""],"futur-irreguliers":["Les radicaux irréguliers du futur","Les terminaisons restent les mêmes, mais le radical change : \"aller\" donne \"ir-\", \"être\" donne \"ser-\", \"avoir\" donne \"aur-\", \"faire\" donne \"fer-\", \"venir\" donne \"viendr-\", \"pouvoir\" donne \"pourr-\", \"voir\" donne \"verr-\", \"vouloir\" donne \"voudr-\". Exemples : \"j'irai\", \"il fera\", \"ils viendront\""],"conditionnel-politesse":["Le conditionnel de politesse","Le \"conditionnel\" adoucit une demande : \"je voudrais\" (plus poli que \"je veux\"), \"pourriez-vous\" (plus poli que \"pouvez-vous\"), \"j'aimerais\". Formation : radical du futur + terminaisons de l'imparfait \"-ais, -ais, -ait, -ions, -iez, -aient\". Exemples : \"je voudrais\", \"pourriez-vous\", \"nous aimerions\""],"cod-pronoms":["Les pronoms COD","\"le\", \"la\", \"l'\" et \"les\" remplacent un nom sans préposition et se placent avant le verbe : \"je vois Paul\" devient \"je le vois\". Négation : \"je ne le vois pas\". Exemples : \"je le vois\", \"elle la prend\", \"tu les aimes\""],"coi-pronoms":["Les pronoms COI","Pour les personnes après \"à\", on emploie \"lui\" (un seul) et \"leur\" (plusieurs) : \"je parle à Marie\" devient \"je lui parle\", \"je téléphone à mes parents\" devient \"je leur téléphone\". Ici, \"leur\" ne prend jamais de -s. Exemples : \"je lui parle\", \"elle leur écrit\""],"pronoms-me-te-nous-vous":["me, te, nous, vous","Ces quatre pronoms servent pour le COD et le COI : \"il me voit\", \"il me parle\". Devant une voyelle, \"me\" et \"te\" deviennent \"m'\" et \"t'\" : \"je t'aime\", \"il m'écoute\". Exemples : \"il me voit\", \"elle nous parle\""],"y-pronom":["Le pronom y","\"y\" remplace \"à\" + chose ou un lieu : \"je vais à Rome\" devient \"j'y vais\". Il se place avant le verbe : \"nous y allons\", \"je n'y vais pas\". Aussi : \"j'y pense\". Exemples : \"j'y vais\", \"nous y allons\""],"en-pronom":["Le pronom en","\"en\" remplace \"du, de la, des\" + nom ou \"de\" + nom. On garde le nombre : \"j'ai deux frères\" devient \"j'en ai deux\". Négation : \"je n'en veux pas\". Exemples : \"j'en veux\", \"nous en avons deux\""],"pronoms-toniques":["Les pronoms toniques","On emploie \"moi, toi, lui, elle, nous, vous, eux, elles\" après une préposition (\"avec moi\", \"chez eux\"), pour insister (\"moi, je\") et seuls (\"Qui est là ? Moi !\"). Aussi après \"c'est\" : \"c'est lui\". Exemples : \"avec moi\", \"chez lui\", \"eux\""],"comparatifs":["Comparer : plus … que","On emploie \"plus … que\", \"moins … que\" et \"aussi … que\" autour d'un adjectif ou d'un adverbe : \"elle est plus rapide que lui\". Avec un nom : \"plus de … que\". Exemples : \"plus grand que\", \"moins cher que\", \"aussi rapide que\""],"superlatifs":["Les superlatifs","On place l'article défini devant \"plus\" ou \"moins\" : \"le plus grand\", \"la plus belle\", \"les moins chers\". Pour dire « parmi », on emploie \"de\" : \"le plus grand de la classe\". Exemples : \"le plus grand\", \"la plus belle\", \"les moins chers\""],"meilleur-mieux":["meilleur ou mieux ?","\"bon\" devient \"meilleur\" (adjectif, il s'accorde) : \"une meilleure idée\". \"bien\" devient \"mieux\" (adverbe, invariable) : \"elle chante mieux\". On ne dit jamais \"plus bon\" ni \"plus bien\". Exemples : \"meilleur\", \"mieux\", \"la meilleure idée\""],"adverbes-ment":["Les adverbes en -ment","On ajoute \"-ment\" à l'adjectif au féminin : \"lent\" donne \"lentement\", \"heureux\" donne \"heureusement\". Après une voyelle, on l'ajoute au masculin : \"vrai\" donne \"vraiment\". \"-ent\" devient \"-emment\" : \"prudent\" donne \"prudemment\". Exemples : \"lentement\", \"vraiment\", \"prudemment\""],"prep-pays-villes":["Pays et villes","Villes : \"à Paris\", \"de Paris\". Pays féminins : \"en France\", \"de France\". Pays masculins : \"au Japon\", \"du Japon\". Pays pluriels : \"aux États-Unis\", \"des États-Unis\". Exemples : \"en France\", \"au Japon\", \"aux États-Unis\", \"à Paris\""],"depuis-pendant-il-y-a":["depuis, pendant, il y a","\"depuis\" + présent : ce qui continue (\"j'habite ici depuis deux ans\"). \"pendant\" + durée : combien de temps cela a duré (\"j'ai dormi pendant huit heures\"). \"il y a\" + durée : depuis combien de temps c'est fini (\"il est parti il y a une heure\"). Exemples : \"depuis deux ans\", \"pendant trois heures\", \"il y a une heure\""],"passe-recent":["Le passé récent : venir de","On conjugue \"venir\" au présent et on ajoute \"de\" + infinitif : \"je viens de finir\", \"nous venons de partir\". Devant une voyelle, \"de\" devient \"d'\" : \"il vient d'arriver\". Exemples : \"je viens de manger\", \"ils viennent de partir\""],"imperatif-negatif":["L'impératif négatif","On place \"ne … pas\" autour du verbe à l'impératif : \"ne pars pas !\", \"ne partons pas !\", \"ne partez pas !\". Les pronoms restent avant le verbe : \"ne le fais pas !\". Exemples : \"ne parle pas\", \"ne partez pas\""],"imperatif-pronoms":["L'impératif avec des pronoms","À l'impératif affirmatif, le pronom suit le verbe avec un trait d'union : \"regarde-moi\", \"parlez-nous\", \"dis-lui\". \"me\" devient \"moi\". À la forme négative, l'ordre est normal : \"ne me regarde pas\". Exemples : \"regarde-moi\", \"dis-lui\", \"donne-le-moi\""],"rel-qui-que":["qui et que","\"qui\" remplace le sujet : \"la femme qui habite ici\". \"que\" remplace le COD : \"le film que nous regardons\". \"que\" devient \"qu'\" devant une voyelle : \"le livre qu'il lit\". Exemples : \"l'homme qui parle\", \"le livre que je lis\""],"rel-ou":["où : le lieu et le temps","\"où\" relie un lieu ou un moment à une proposition : \"la maison où elle habite\", \"le jour où nous sommes partis\". Il s'emploie pour le lieu comme pour le temps. Exemples : \"la ville où j'habite\", \"le jour où\""],"il-faut":["il faut","\"il faut\" + infinitif exprime l'obligation : \"il faut partir\". \"il faut\" + nom exprime le besoin : \"il faut du temps\". \"il ne faut pas\" exprime l'interdiction. C'est un verbe impersonnel : seulement \"il\". Exemples : \"il faut travailler\", \"il faut du temps\""],"neg-jamais-plus-rien":["jamais, plus, rien, personne","Ils remplacent \"pas\" : \"ne … jamais\", \"ne … plus\", \"ne … rien\", \"ne … personne\". \"rien\" et \"personne\" peuvent aussi être sujets : \"personne ne vient\". Exemples : \"je ne mange jamais\", \"il ne travaille plus\", \"nous ne voyons personne\""],"quantite-de":["Quantité + de","Après un mot de quantité, on emploie \"de\", sans article : \"beaucoup de travail\", \"un peu de sucre\", \"assez de temps\", \"trop de monde\", \"peu de gens\", \"une bouteille d'eau\". Exemples : \"beaucoup de travail\", \"un peu de sucre\", \"trop de monde\""],"c-est-il-est":["c'est ou il est ?","On dit \"il est\" / \"elle est\" + adjectif ou profession seuls : \"il est médecin\", \"elle est gentille\". On dit \"c'est\" quand il y a un article ou un possessif : \"c'est un médecin\", \"c'est mon frère\". Exemples : \"c'est un médecin\", \"il est médecin\", \"elle est gentille\""],"q-inversion":["L'inversion","Dans un français soutenu, le verbe se place avant le pronom sujet, relié par un trait d'union : \"parlez-vous ?\", \"où vas-tu ?\", \"que font-ils ?\". Si le verbe finit par une voyelle, on ajoute \"-t-\" : \"aime-t-il ?\". Exemples : \"parlez-vous\", \"où vas-tu\", \"que font-ils\""],"q-qui-que-quoi":["Qui, que, quoi","\"qui\" interroge sur les personnes, \"que\" et \"qu'est-ce que\" sur les choses : \"qu'est-ce que tu fais ?\". Après une préposition, on dit \"qui\" (personnes) ou \"quoi\" (choses) : \"avec qui ?\", \"de quoi parles-tu ?\". Exemples : \"qui est-ce ?\", \"qu'est-ce que tu fais ?\", \"de quoi parles-tu ?\""],"adj-irreguliers":["beau, nouveau, vieux","Ces trois adjectifs ont une forme spéciale devant une voyelle au masculin : \"beau\" donne \"bel\", \"nouveau\" donne \"nouvel\", \"vieux\" donne \"vieil\". Féminin : \"belle\", \"nouvelle\", \"vieille\". Pluriel : \"beaux\", \"nouveaux\", \"vieux\". Exemples : \"un bel homme\", \"une nouvelle voiture\", \"un vieil ami\""],"connecteurs-temps":["D'abord, ensuite, enfin","\"d'abord\", \"ensuite\" ou \"puis\", \"après\", \"enfin\" mettent les actions dans l'ordre : \"d'abord je mange, puis je pars, enfin j'arrive\". Exemples : \"d'abord\", \"ensuite\", \"puis\", \"enfin\""],"si-present-futur":["si + présent, futur","Pour une possibilité réelle : \"si\" + présent dans la condition, futur (ou impératif) dans le résultat. \"si tu viens, je serai content\", \"si vous avez le temps, appelez-moi\". On ne met jamais le futur après \"si\". Devant \"il\", on écrit \"s'il\". Exemples : \"si tu viens, nous mangerons\", \"s'il pleut, je resterai\""],"savoir-connaitre":["savoir ou connaître ?","\"savoir\" s'emploie pour les faits et les savoir-faire : \"je sais nager\", \"je sais où il habite\". \"connaître\" s'emploie pour les personnes, les lieux et les choses qu'on a déjà rencontrés : \"je connais Marie\", \"je connais cette ville\". Exemples : \"je sais nager\", \"je connais Paris\""],"pres-irreguliers-2":["D'autres verbes irréguliers","Apprenez-les par groupes : \"lire\" (\"nous lisons\"), \"dire\" (\"vous dites\"), \"écrire\" (\"ils écrivent\"), \"voir\" (\"nous voyons\"), \"boire\" (\"ils boivent\"). La forme \"nous\" aide à construire l'imparfait. Exemples : \"nous lisons\", \"vous dites\", \"ils écrivent\""],"meteo-il":["La météo","On emploie \"il fait\" + adjectif (\"il fait beau, froid, chaud\") et un verbe pour la pluie et la neige (\"il pleut\", \"il neige\"). Le sujet \"il\" est vide et ne change jamais. Question : \"quel temps fait-il ?\" Exemples : \"il fait beau\", \"il pleut\", \"il neige\""],"profession-sans-article":["Pas d'article pour les métiers","Après \"être\", une profession, une nationalité ou une religion s'emploie sans article : \"il est médecin\", \"elle est française\". Avec un adjectif, on dit \"c'est un\" : \"c'est un bon médecin\". Exemples : \"elle est infirmière\", \"il est professeur\""],"subj-il-faut-que":["Le subjonctif : il faut que","Après \"il faut que\", on emploie le subjonctif. Verbes réguliers : on prend le radical du présent de \"ils\" et on ajoute \"-e, -es, -e, -ions, -iez, -ent\" : \"ils partent\" donne \"que je parte\". Les formes \"nous\" et \"vous\" ressemblent à l'imparfait. Exemples : \"il faut que tu viennes\", \"il faut que je parte\""],"subj-vouloir-que":["vouloir que + subjonctif","Quand le sujet change, \"vouloir que\", \"préférer que\", \"aimer mieux que\" et \"demander que\" prennent le subjonctif : \"je veux que tu viennes\". Si le sujet est le même, on emploie l'infinitif : \"je veux venir\". Exemples : \"je veux que tu viennes\", \"elle veut que nous partions\""],"subj-irreguliers":["Les subjonctifs irréguliers","À apprendre par cœur : \"être\" (\"que je sois\"), \"avoir\" (\"que j'aie, qu'il ait\"), \"aller\" (\"que j'aille\"), \"faire\" (\"que je fasse\"), \"pouvoir\" (\"que je puisse\"), \"savoir\" (\"que je sache\"), \"vouloir\" (\"que je veuille\"). Exemples : \"que je sois\", \"qu'il ait\", \"que nous allions\", \"qu'ils fassent\""],"subj-emotions":["Les sentiments + subjonctif","Après les expressions de sentiment (\"être content que\", \"être triste que\", \"regretter que\", \"avoir peur que\", \"être surpris que\"), on emploie le subjonctif quand le sujet change. Exemples : \"je suis content que tu sois là\", \"elle regrette que nous partions\""],"subj-vs-indic":["Indicatif ou subjonctif ?","La certitude se construit avec l'indicatif : \"je pense que\", \"je sais que\", \"il est sûr que\". Le doute, la négation et la volonté se construisent avec le subjonctif : \"je ne pense pas que\", \"je doute que\", \"il faut que\". \"Penser que\" en question admet les deux. Exemples : \"je pense qu'il a raison\", \"je ne pense pas qu'il ait raison\""],"subj-conjonctions":["Conjonctions + subjonctif","Certaines conjonctions demandent toujours le subjonctif : \"pour que\", \"avant que\", \"bien que\", \"à condition que\", \"jusqu'à ce que\". \"après que\" se construit avec l'indicatif. Exemples : \"pour que tu comprennes\", \"avant que tu partes\", \"bien qu'il soit fatigué\""],"si-imparfait-cond":["si + imparfait, conditionnel","Pour une situation imaginaire ou peu probable : \"si\" + imparfait, puis conditionnel dans le résultat. \"si j'étais riche, je voyagerais\". On n'emploie jamais le conditionnel après \"si\". Exemples : \"si j'avais de l'argent\", \"j'achèterais une maison\""],"cond-usage":["Le conditionnel : conseils et souhaits","Le \"conditionnel\" sert à donner un conseil (\"tu devrais\"), à exprimer un souhait (\"j'aimerais\") et à faire une suggestion polie (\"on pourrait\"). Avec \"devoir\", \"pouvoir\" et \"vouloir\", il est très fréquent. Exemples : \"tu devrais dormir\", \"nous aimerions voyager\""],"cond-passe-regret":["Les regrets sur le passé","Pour ce qui ne s'est pas passé : \"si\" + plus-que-parfait, conditionnel passé. \"si tu avais étudié, tu aurais réussi\". Le conditionnel passé : \"avoir\" ou \"être\" au conditionnel + participe passé. Exemples : \"si j'avais su\", \"je serais venu\""],"plus-que-parfait-forme":["Le plus-que-parfait : la formation","Auxiliaire à l'\"imparfait\" + participe passé : \"j'avais mangé\", \"elle était partie\", \"nous nous étions levés\". Les mêmes règles que pour le passé composé décident entre \"avoir\" et \"être\" et pour l'accord. Exemples : \"j'avais fini\", \"nous étions partis\", \"elle avait mangé\""],"plus-que-parfait-usage":["Le plus-que-parfait : l'emploi","On emploie le \"plus-que-parfait\" pour une action qui s'est passée avant une autre action passée ou avant un moment du passé : \"quand je suis arrivé, il était déjà parti\". Il explique souvent une cause : \"il était fatigué, il n'avait pas dormi\". Exemples : \"le film avait déjà commencé\", \"il n'avait pas dormi\""],"di-present":["Le discours rapporté (présent)","Avec \"dire que\", \"répondre que\", \"expliquer que\" au présent, le temps de la proposition rapportée ne change pas ; seuls les pronoms et des mots comme \"mon\" changent : \"« j'ai faim »\" donne \"il dit qu'il a faim\". Exemples : \"il dit qu'il est fatigué\", \"elle répond qu'elle ne sait pas\""],"di-questions":["Les questions rapportées","Les questions oui/non utilisent \"si\" : \"il demande si tu viens\". Les mots interrogatifs restent : \"où, quand, comment, pourquoi\". \"Qu'est-ce que\" devient \"ce que\", \"qu'est-ce qui\" devient \"ce qui\". L'ordre des mots est celui d'une phrase affirmative. Exemples : \"il demande si je viens\", \"elle demande où j'habite\""],"di-passe":["Le discours rapporté (passé)","Après \"a dit que\", les temps changent : le présent devient \"imparfait\", le futur devient \"conditionnel\", le passé composé devient \"plus-que-parfait\". Les marqueurs de temps changent aussi : \"demain\" devient \"le lendemain\". Exemples : \"il a dit qu'il était fatigué\", \"elle a répondu qu'elle viendrait\""],"gerondif-formation":["Le gérondif : la formation","On prend la forme \"nous\" du présent, on enlève \"-ons\", on ajoute \"-ant\" et on place \"en\" devant : \"nous travaillons\" donne \"en travaillant\". Exceptions : \"être\" donne \"en étant\", \"avoir\" donne \"en ayant\", \"savoir\" donne \"en sachant\". Exemples : \"en travaillant\", \"en lisant\", \"en finissant\""],"gerondif-usage":["Le gérondif : l'emploi","Le \"gérondif\" exprime deux actions simultanées (\"il chante en travaillant\"), la manière (\"on apprend en lisant\") ou une condition (\"en tournant à gauche, vous verrez la poste\"). Les deux verbes ont le même sujet. Exemples : \"on apprend en lisant\", \"il s'est blessé en jouant\""],"rel-dont":["dont : le pronom avec de","\"dont\" remplace \"de\" + nom : \"je parle de ce livre\" devient \"le livre dont je parle\". Il exprime aussi la possession : \"la fille dont le père est médecin\". Et après \"avoir besoin de\" : \"ce dont j'ai besoin\". Exemples : \"le livre dont je parle\", \"la fille dont le père est médecin\""],"rel-ce-qui-ce-que":["ce qui, ce que, ce dont","Quand il n'y a pas de nom avant, on emploie \"ce qui\" (sujet), \"ce que\" (COD) et \"ce dont\" (avec \"de\") : \"ce qui se passe\", \"ce que tu veux\", \"ce dont j'ai besoin\". Exemples : \"ce que tu veux\", \"ce qui se passe\", \"ce dont j'ai besoin\""],"pronoms-ordre":["Deux pronoms ensemble","Ordre avant le verbe : \"me, te, nous, vous\" + \"le, la, les\" + \"lui, leur\" + \"y\" + \"en\". \"me le\", \"te la\", \"nous les\", mais \"le lui\", \"les leur\" : \"je le lui donne\". Exemples : \"je le lui donne\", \"elle me les envoie\""],"y-en-ensemble":["il y en a","Quand \"y\" et \"en\" sont ensemble, \"y\" vient en premier : \"il y en a\", \"il n'y en a plus\". \"en\" garde la quantité : \"il y en a trois\". Exemples : \"il y en a\", \"nous y en avons\""],"imperatif-ordre-pronoms":["Impératif : l'ordre des pronoms","À l'affirmatif : verbe + COD (\"le, la, les\") + COI (\"moi, lui, nous, leur\") + \"y\" / \"en\" : \"donne-le-moi\", \"dis-le-lui\". \"moi\" devient \"m'\" devant \"en\" : \"donne-m'en\". Au négatif : ordre normal, \"ne me le donne pas\". Exemples : \"donne-le-moi\", \"dis-le-lui\", \"donne-m'en\""],"pronoms-possessifs":["Les pronoms possessifs","Ils remplacent un possessif + nom et s'accordent avec le nom : \"le mien, la mienne, les miens, les miennes\", \"le tien\", \"le sien\", \"le nôtre\", \"le vôtre\", \"le leur\". \"Où est ma clé ? — Voici la mienne.\" Exemples : \"le mien\", \"la tienne\", \"les nôtres\""],"pronoms-demonstratifs":["celui, celle, ceux, celles","Ils remplacent « la personne » ou « la chose » et sont suivis de \"de\", \"qui\", \"que\" ou \"-ci / -là\" : \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\", \"celles-là\". Exemples : \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\""],"pronoms-indefinis":["Les pronoms indéfinis","\"quelqu'un\", \"quelque chose\", \"personne\", \"rien\", \"chacun\", \"plusieurs\". Devant un adjectif, on emploie \"de\" : \"quelque chose de bon\". Exemples : \"quelqu'un\", \"quelque chose de sucré\", \"chacun\""],"adj-indefinis":["chaque, plusieurs, quelques","\"chaque\" + nom singulier, \"plusieurs\" et \"quelques\" + nom pluriel. \"tout\" s'accorde : \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Exemples : \"chaque élève\", \"plusieurs voitures\", \"toute la journée\""],"pc-accord-cod":["L'accord du participe avec avoir","Avec \"avoir\", le participe s'accorde avec le COD seulement s'il est placé avant le verbe : \"j'ai acheté des fleurs\", mais \"les fleurs que j'ai achetées\", \"je les ai vues\". Exemples : \"les fleurs que j'ai achetées\", \"je les ai vues\""],"passif-forme":["La voix passive","\"être\" (au temps voulu) + participe passé accordé avec le sujet + \"par\" : \"la lettre est écrite par Paul\", \"les maisons ont été détruites par le feu\". Le COD de la phrase active devient le sujet. Exemples : \"le roman est écrit par\", \"la porte est ouverte par\""],"se-passif":["Le passif avec se","Un verbe à la troisième personne avec \"se\" a un sens passif, sans complément d'agent : \"le vin se vend ici\", \"ça ne se dit pas\", \"cela se voit\". Très courant à l'oral et dans les règles. Exemples : \"ça se dit\", \"ce produit se vend partout\""],"etre-en-train-de":["être en train de","\"être en train de\" + infinitif insiste sur une action qui se passe en ce moment : \"je suis en train de lire\". On l'emploie pour insister : \"ne l'appelle pas, il est en train de dormir\". Exemples : \"je suis en train de manger\", \"ils sont en train de partir\""],"pc-avoir-transitif":["Un même verbe, deux auxiliaires","Quand \"sortir, monter, descendre, passer, rentrer, retourner\" ont un COD, l'auxiliaire est \"avoir\" : \"j'ai sorti la voiture\", \"elle a monté les escaliers\". Sans COD, on emploie \"être\" : \"elle est sortie\". Exemples : \"il a sorti la valise\", \"elle a monté les escaliers\""],"futur-anterieur":["Le futur antérieur","\"avoir\" ou \"être\" au futur simple + participe passé : \"j'aurai fini\", \"elle sera partie\". Il exprime une action terminée avant une autre action future : \"quand j'aurai fini, je t'appellerai\". Exemples : \"quand j'aurai fini\", \"dès qu'elle sera arrivée\""],"quand-futur":["quand + futur","Après \"quand\", \"dès que\", \"lorsque\" et \"aussitôt que\", on emploie le futur quand l'action est dans l'avenir : \"dès qu'il arrivera, nous partirons\". \"Si\" est l'exception : il n'est jamais suivi du futur. Exemples : \"quand je serai grand\", \"dès qu'il arrivera\""],"connecteurs-cause-consequence":["Cause et conséquence","\"car\" et \"parce que\" donnent une raison ; \"comme\" et \"puisque\" ouvrent la phrase avec une raison connue : \"comme il pleut, je reste\". \"donc\" et \"alors\" donnent le résultat : \"il pleut, donc je reste\". Exemples : \"donc\", \"car\", \"comme\", \"puisque\""],"connecteurs-opposition":["L'opposition","\"mais\", \"pourtant\" et \"cependant\" opposent deux idées. \"alors que\" compare deux faits : \"elle aime le thé, alors que son mari préfère le café\". \"malgré\" + nom exprime une opposition : \"malgré la pluie\". Exemples : \"pourtant\", \"alors que\", \"malgré la pluie\""],"but-pour-afin-de":["Le but","Avec le même sujet : \"pour\" ou \"afin de\" + infinitif : \"je travaille pour gagner de l'argent\". Avec un sujet différent : \"pour que\" ou \"afin que\" + subjonctif : \"il parle lentement pour que nous comprenions\". Exemples : \"pour gagner de l'argent\", \"afin de rentrer\", \"pour que nous comprenions\""],"neg-ne-que-ni":["ne … que, ni … ni, aucun","\"ne … que\" exprime la restriction : \"je n'ai que dix euros\". \"ne … ni … ni\" exclut deux choses : \"elle ne mange ni viande ni poisson\". \"ne … aucun\" signifie « pas un seul » : \"il n'a aucun ami\". Exemples : \"je n'ai que dix euros\", \"ni viande ni poisson\", \"aucun ami\""],"neg-infinitif":["L'infinitif négatif","Les deux parties de la négation se placent ensemble devant l'infinitif : \"ne pas partir\", \"ne plus fumer\", \"ne jamais mentir\". \"Il m'a demandé de ne pas fumer\". Exemples : \"ne pas fumer\", \"ne plus travailler\", \"ne jamais mentir\""],"q-lequel":["Lequel : quel parmi d'autres","\"lequel\" remplace \"quel\" + nom et s'accorde : \"lequel\" (m. sing.), \"laquelle\" (f. sing.), \"lesquels\" (m. pl.), \"lesquelles\" (f. pl.). \"Quel sac ? Lequel ?\" Après \"à\" et \"de\" : \"auquel\", \"duquel\". Exemples : \"lequel\", \"laquelle\", \"lesquels\""],"exclamations":["Les exclamations","\"quel\" + nom : \"quelle belle journée !\". \"comme\" ou \"que\" + proposition : \"comme il fait chaud !\", \"que c'est joli !\". Notez l'espace avant \"!\" en français. Exemples : \"quelle belle journée !\", \"comme il fait chaud !\", \"que c'est joli !\""],"adv-place-pc":["Les adverbes courts au passé composé","Les adverbes courts et fréquents (\"déjà, bien, mal, souvent, toujours, encore, trop, beaucoup\") se placent entre l'auxiliaire et le participe : \"j'ai déjà mangé\", \"il a bien compris\". Les adverbes de lieu et les adverbes longs se placent après. Exemples : \"elle a déjà fini\", \"il a bien compris\""],"comparatifs-avances":["De plus en plus, plus … plus","\"de plus en plus\", \"de moins en moins\", \"plus … plus\" et \"autant de … que\" expriment une progression ou une égalité : \"elle a autant de livres que moi\". Exemples : \"de plus en plus froid\", \"plus on travaille, plus on apprend\", \"autant de livres\""],"prep-verbes":["Les verbes avec préposition","Beaucoup de verbes demandent une préposition fixe : \"penser à\", \"s'intéresser à\", \"répondre à\", \"parler de\", \"avoir besoin de\", \"avoir envie de\", \"rêver de\". Apprenez-les avec le verbe. Exemples : \"penser à\", \"parler de\", \"avoir besoin de\", \"s'intéresser à\""],"prep-temps-en-dans":["en ou dans ?","\"dans\" + durée : le moment où quelque chose va arriver, à partir de maintenant (\"le film commence dans une heure\"). \"en\" + durée : le temps que prend une action (\"il a lu ce livre en deux jours\"). \"en\" s'emploie aussi avec les mois et les années : \"en mai\", \"en 1998\". Exemples : \"dans une heure\", \"en deux jours\""],"inf-apres-prepositions":["Prépositions + infinitif","\"avant de\" + infinitif, \"après\" + infinitif passé (\"avoir\" ou \"être\" + participe), \"sans\" + infinitif : \"avant de partir\", \"après avoir mangé\", \"sans dire au revoir\". Le sujet doit être le même. Exemples : \"avant de manger\", \"après avoir mangé\", \"sans dire\""],"faire-causatif":["faire + infinitif","\"faire\" + infinitif signifie demander à quelqu'un de faire quelque chose (\"je fais réparer ma voiture\") ou provoquer une action (\"il fait rire les enfants\"). L'infinitif suit directement \"faire\". Exemples : \"je fais réparer ma voiture\", \"il fait rire les enfants\""],"verbes-perception":["Voir et entendre + infinitif","Après \"voir\", \"entendre\", \"regarder\", \"écouter\", \"sentir\", on met un infinitif : \"je les entends jouer\", \"nous voyons passer le train\". Le pronom est le COD du verbe de perception. Exemples : \"je les entends chanter\", \"nous voyons passer le train\""],"voyelle-liaison-ecrite":["Formes spéciales devant une voyelle","Devant une voyelle ou un h muet, certains mots changent pour faciliter la prononciation : \"ma\" devient \"mon\" (\"mon amie\"), \"ce\" devient \"cet\" (\"cet homme\"), \"beau\" devient \"bel\" (\"un bel arbre\"), \"nouveau\" devient \"nouvel\", \"vieux\" devient \"vieil\". Exemples : \"mon amie\", \"cet homme\", \"un bel arbre\""],"tout-tous-toutes":["tout, tous, toute, toutes","Comme adjectif, \"tout\" s'accorde : \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Comme pronom, il signifie « toutes les choses » (\"j'ai tout compris\") ou « tout le monde » (\"ils sont tous là\", avec le -s final prononcé). Exemples : \"tous les jours\", \"toute la journée\", \"ils sont tous là\""],"subj-after-bien-que":["Bien que + subjonctif","\"bien que\", \"quoique\" et \"encore que\" expriment la concession et se construisent toujours avec le subjonctif, même quand le fait est certain. Dites \"Bien que le projet soit coûteux, nous continuons\", pas \"bien que le projet est\". Exemples : \"Bien qu'il pleuve, nous sortons\", \"Quoiqu'elle soit jeune, elle dirige l'équipe\""],"subj-after-pour-que":["But : pour que, afin que","\"pour que\" et \"afin que\" introduisent un but et sont suivis du subjonctif. Le sujet de la subordonnée est généralement différent du sujet principal : \"Je répète pour que vous compreniez\". Avec le même sujet, utilisez \"pour\" ou \"afin de\" plus l'infinitif. Exemples : \"Il parle lentement pour que nous comprenions\", \"Elle écrit afin que tout soit clair\""],"subj-after-avant-que":["Limites de temps : avant que","\"avant que\" et \"jusqu'à ce que\" se construisent avec le subjonctif, car l'action n'est pas encore réalisée. Après \"avant que\", on ajoute souvent un \"ne\" sans valeur négative : \"avant qu'il ne parte\". Utilisez \"avant de\" plus l'infinitif si le sujet est le même. Exemples : \"Attends jusqu'à ce que je revienne\", \"Appelle avant que nous ne partions\""],"subj-a-moins-que-ne":["Exception : à moins que","\"à moins que\" signifie \"sauf si\" et exige le subjonctif. Le français soutenu ajoute souvent un \"ne\" explétif devant le verbe (\"à moins qu'il ne vienne\"), qui n'est pas une vraie négation. N'employez ni le conditionnel ni le futur après cette locution. Exemples : \"Je sors, à moins qu'il ne pleuve\", \"à moins que vous ne soyez occupé\""],"subj-a-condition-que":["Condition : à condition que","\"à condition que\" et \"pourvu que\" signifient \"si et seulement si\" et se construisent avec le subjonctif, jamais avec le futur ou le conditionnel. \"Pourvu que\" peut aussi ouvrir une phrase pour exprimer un souhait : \"Pourvu qu'il vienne !\". Exemples : \"Je viendrai à condition que vous m'invitiez\", \"Pourvu que tout se passe bien\""],"subj-vs-ind-opinion":["Verbes d'opinion : le mode","Après \"penser que\" et \"croire que\" à la forme affirmative, on emploie l'indicatif : \"Je pense qu'il a raison\". À la forme négative ou dans une question avec inversion, le doute apparaît et on emploie le subjonctif : \"Je ne pense pas qu'il ait raison\". Le mode dépend du degré de certitude du locuteur. Exemples : \"Je crois qu'elle viendra\", \"Je ne crois pas qu'elle vienne\""],"subj-emotion-doubt":["Sentiment, doute, nécessité","Les verbes d'émotion (\"être content que\", \"regretter que\"), de doute (\"douter que\") et de nécessité (\"il faut que\", \"il est essentiel que\") sont suivis du subjonctif quand les sujets sont différents. La subordonnée exprime une réaction ou un besoin, pas un simple fait. Exemples : \"Je suis ravi que vous veniez\", \"Il faut que nous partions\""],"subj-irregular-forms":["Radicaux irréguliers du subjonctif","Sept verbes courants ont des radicaux irréguliers au subjonctif : \"être\" (sois, soyons), \"avoir\" (aie, ayons), \"aller\" (aille, allions), \"faire\" (fasse), \"pouvoir\" (puisse), \"savoir\" (sache), \"vouloir\" (veuille). Apprenez les formes entières ; les formes nous et vous de \"être\", \"avoir\", \"aller\" et \"vouloir\" ont aussi leur propre radical. Exemples : \"qu'elle aille\", \"que vous sachiez\", \"que tu aies\""],"subj-passe":["Le subjonctif passé","Le subjonctif passé se forme avec le subjonctif de \"avoir\" ou \"être\" plus le participe passé. Il montre que l'action est terminée avant celle du verbe principal : \"Je suis content que tu sois venu\". Choisissez l'auxiliaire comme au passé composé et gardez l'accord. Exemples : \"Il faut qu'ils aient fini\", \"Bien qu'elle soit partie\""],"subj-vs-infinitive":["Subjonctif ou infinitif","Quand les deux verbes ont le même sujet, le français préfère l'infinitif : \"Je veux partir\". Quand le sujet change, on emploie \"que\" plus le subjonctif : \"Je veux que tu partes\". Cela vaut aussi pour les souhaits, les émotions et de nombreuses conjonctions (\"avant de\" ou \"avant que\"). Exemples : \"Elle est contente d'être là\", \"Elle est contente que vous soyez là\""],"subj-superlative-relative":["Subjonctif après un superlatif","Après un superlatif (\"le plus\", \"le meilleur\") ou après \"seul\", \"premier\", \"dernier\", \"unique\", la proposition relative se met au subjonctif, car l'énoncé exprime un jugement personnel. Avec \"jamais\", le subjonctif passé est courant : \"le plus beau film que j'aie vu\". Exemples : \"le seul homme qui sache\", \"la première fois que je le voie\""],"subj-relative-search":["Subjonctif et antécédent recherché","Quand une relative décrit quelque chose que l'on cherche, que l'on souhaite ou dont on doute de l'existence, on emploie le subjonctif : \"Je cherche un livre qui soit simple\". Si l'on sait que la chose existe, on emploie l'indicatif : \"J'ai un livre qui est simple\". Déclencheurs typiques : \"chercher\", \"vouloir\", \"il n'y a personne qui\", questions sur l'existence. Exemples : \"Y a-t-il quelqu'un qui puisse m'aider ?\""],"cond-passe-news":["Conditionnel pour une info non confirmée","Les journalistes emploient le conditionnel, souvent le conditionnel passé, pour rapporter une information non confirmée : \"Le ministre aurait démissionné\". Il signale \"d'après certaines sources\" ou \"selon la rumeur\" et évite que l'auteur garantisse le fait. Utilisez le conditionnel présent pour une rumeur actuelle : \"Il serait malade\". Exemples : \"Deux personnes seraient blessées\", \"selon certaines sources, le vol aurait été annulé\""],"si-plus-que-parfait":["Si + plus-que-parfait irréel","Pour une condition irréelle dans le passé, on emploie \"si\" plus le plus-que-parfait, et le conditionnel passé dans la principale : \"Si j'avais su, je serais venu\". Ne mettez jamais de conditionnel après \"si\" dans ce sens. La principale montre ce qui ne s'est pas produit. Exemples : \"Si elle avait étudié, elle aurait réussi\", \"Si nous étions partis, nous aurions vu le concert\""],"si-mixed-conditions":["Phrases conditionnelles mixtes","Une phrase conditionnelle mixte relie une condition passée à un résultat présent : \"si\" plus plus-que-parfait, puis le conditionnel présent. Des mots de temps comme \"maintenant\" ou \"aujourd'hui\" dans la principale montrent que la conséquence est encore vraie. Exemple : \"Si tu avais écouté, tu comprendrais\". Comparez avec le schéma entièrement passé : \"tu aurais compris\""],"hypothese-au-cas-ou":["Précaution : au cas où","\"au cas où\" exprime une précaution contre un événement possible et se construit avec le conditionnel, pas avec le subjonctif ni le futur. Elle signifie \"pour le cas où\". Elle peut se placer au début ou à la fin de la phrase. Exemples : \"Prenez un parapluie au cas où il pleuvrait\", \"Au cas où tu serais en retard, appelle-moi\""],"apres-que-indicatif":["après que + indicatif","\"après que\" et \"dès que\" énoncent un fait réellement arrivé, ils se construisent donc avec l'indicatif, pas avec le subjonctif (contrairement à \"avant que\"). Le verbe après \"après que\" est à un temps composé, antérieur au verbe principal : \"Après qu'il a fini, il est rentré\". Après \"dès que\" avec un verbe principal au futur, on emploie le futur antérieur : \"Dès que tu auras fini, appelle-moi\""],"concordance-des-temps":["Concordance des temps","Quand le verbe principal est au passé, le verbe de la subordonnée recule : le présent devient imparfait, le passé composé devient plus-que-parfait, le futur devient conditionnel. Ne mélangez pas un verbe principal au passé et un verbe subordonné au présent : \"Il pensait que nous étions partis\". Exemples : \"Je savais que tu viendrais\", \"Elle disait qu'elle était fatiguée\""],"discours-indirect-passe":["Discours indirect au passé","Dans le discours indirect après un verbe au passé (\"elle a dit que\"), les temps changent : présent en imparfait, passé composé en plus-que-parfait, futur en conditionnel. Les mots de temps changent aussi : \"demain\" devient \"le lendemain\", \"hier\" devient \"la veille\", \"aujourd'hui\" devient \"ce jour-là\". Exemple : \"Il a dit qu'il viendrait le lendemain\""],"discours-indirect-questions":["Questions indirectes","Dans les questions indirectes, on garde l'ordre normal des mots et on ne met pas de point d'interrogation. \"Est-ce que\" et les questions fermées deviennent \"si\" : \"Il a demandé si je venais\". \"Qu'est-ce que\" devient \"ce que\", et \"qu'est-ce qui\" devient \"ce qui\". Les temps changent après un verbe au passé. Exemples : \"Elle m'a demandé ce que je voulais\", \"Il voulait savoir ce qui se passait\""],"discours-indirect-ordres":["Rapporter ordres et demandes","Pour rapporter un ordre ou une demande, on emploie \"dire de\" ou \"demander de\" plus l'infinitif : \"Elle m'a dit de rentrer\". La personne visée prend \"à\" ou un pronom : \"Il a demandé à ses voisins de baisser la musique\". Un ordre négatif garde \"ne pas\" ensemble devant l'infinitif : \"Il nous a dit de ne pas toucher aux câbles\""],"accord-participe-cod-avant":["Accord avec un COD placé avant","Avec \"avoir\", le participe passé s'accorde avec le COD seulement s'il est placé avant le verbe. Cherchez \"que\", un pronom comme \"les\" ou un mot interrogatif : \"Les lettres que Marie a écrites\", \"Quelle robe as-tu choisie ?\". Si le COD vient après, il n'y a pas d'accord : \"Marie a écrit des lettres\""],"accord-participe-pronominaux":["Accord des verbes pronominaux","Au passé composé d'un verbe pronominal, le participe s'accorde avec le pronom réfléchi quand celui-ci est COD : \"Les amies se sont retrouvées\". Il reste invariable quand le pronom est COI ou qu'un autre complément suit : \"Elle s'est lavé les mains\", \"Ils se sont envoyé des messages\". Demandez-vous si \"se\" signifie \"à qui ?\" ou \"qui ?\""],"participe-present-gerondif":["Participe, gérondif, adjectif","Le gérondif \"en + -ant\" dit comment ou quand quelque chose se passe et reste invariable : \"Il s'est blessé en coupant du bois\". Le participe présent remplace une proposition et reste lui aussi invariable : \"Les enfants jouant dans le jardin\". L'adjectif verbal s'accorde avec son nom : \"une histoire fascinante\", \"des résultats surprenants\""],"passif-et-alternatives":["Le passif et ses alternatives","Le passif se forme avec \"être\" + participe passé : \"Les résultats ont été annoncés par le jury\". Le français préfère souvent des alternatives : un pronominal pour les faits généraux (\"Le fromage se mange après le plat\"), \"on\", ou \"se faire\" pour ce qui arrive au sujet (\"Il s'est fait voler son sac\")"],"causatif-faire-laisser":["Causatif : faire et laisser","\"Faire\" + infinitif signifie faire en sorte que quelque chose soit fait : \"Nous avons fait refaire la cuisine\". \"Laisser\" + infinitif signifie permettre : \"Le professeur a laissé les élèves partir\". Le participe \"fait\" reste invariable devant l'infinitif : \"Ce film m'a fait pleurer\""],"pronoms-relatifs-composes":["Pronoms relatifs composés","Après une préposition, on emploie \"lequel\", \"laquelle\", \"lesquels\" ou \"lesquelles\", selon le nom : \"la table sur laquelle\", \"les amis chez lesquels\". Avec \"à\", ils se contractent : \"auquel\", \"auxquels\", \"auxquelles\", \"à laquelle\". Avec \"de\", on obtient \"duquel\", \"desquels\", \"de laquelle\""],"pronom-relatif-dont":["Le pronom relatif dont","\"Dont\" remplace \"de\" + nom dans une proposition relative : \"L'ordinateur dont j'ai besoin\" (avoir besoin de). Il exprime aussi la possession, avec le nom juste après : \"l'écrivain dont le dernier roman\". Et il introduit une partie d'un groupe : \"trois enfants, dont deux vivent à l'étranger\""],"ce-qui-ce-que-ce-dont":["Ce qui, ce que, ce dont","\"Ce\" + pronom relatif renvoie à une idée ou à une chose non nommée. \"Ce qui\" est sujet (\"Ce qui m'inquiète\"), \"ce que\" est objet (\"ce que tu veux\"). Employez \"ce dont\" pour les verbes avec \"de\" (\"ce dont tu as envie\") et \"ce à quoi\" pour les verbes avec \"à\" (\"ce à quoi il s'intéresse\")"],"pronoms-doubles-ordre":["Ordre de deux pronoms","Devant le verbe, placez d'abord le pronom indirect pour me, te, nous et vous : \"Je te le rends\". À la troisième personne, le pronom direct vient d'abord : \"Je le lui donne\" ; \"en\" vient toujours en dernier : \"Je lui en ai parlé\". Après un impératif affirmatif, l'ordre est direct puis indirect : \"Donne-les-moi\""],"pronoms-y-en-avances":["Y et en : emplois avancés","\"En\" remplace \"de\" + nom ou une quantité, et le nombre reste : \"J'en ai acheté trois\". \"Y\" remplace \"à\" ou un lieu : \"J'y pense tout le temps\". À l'impératif affirmatif, ils suivent le verbe et se combinent : \"Donnez-m'en un kilo\""],"mise-en-relief":["Mise en relief : c'est...qui/que","\"C'est ... qui\" met en relief le sujet et \"c'est ... que\" met en relief un objet ou un complément : \"C'est moi qui ai fait le gâteau\", \"C'est demain que nous partons\". Avec un nom pluriel, on emploie \"ce sont\" : \"Ce sont mes voisins que j'ai invités\". Le verbe après \"qui\" s'accorde avec l'élément mis en relief"],"inversion-peut-etre":["Inversion après un adverbe de phrase","En français soutenu, \"peut-être\", \"sans doute\" et \"aussi\" (au sens de \"par conséquent\") en début de phrase entraînent l'inversion sujet-verbe : \"Peut-être viendra-t-il demain\". Avec un sujet nominal, on le reprend par un pronom. On ajoute \"-t-\" quand le verbe se termine par une voyelle devant \"il\" ou \"elle\" : \"viendra-t-elle\""],"ne-expletif":["Le ne explétif","Après les verbes de crainte (\"craindre que\"), \"avant que\" et les comparatifs d'inégalité, le français soutenu ajoute un \"ne\" sans valeur négative : \"Je crains qu'il ne pleuve\", \"avant qu'il ne fasse nuit\", \"plus grand que je ne pensais\". Il est facultatif à l'oral et ne s'accompagne jamais de \"pas\""],"connecteurs-concession-opposition":["Concession et opposition","\"Bien que\" + subjonctif et \"malgré\" + nom expriment la concession : \"Malgré la pluie, nous sommes sortis\". \"Alors que\" + indicatif oppose deux faits : \"Paul adore la mer, alors que sa femme préfère la montagne\". \"Pourtant\", \"cependant\" et \"en revanche\" relient deux phrases"],"nominalisation":["Transformer les verbes en noms","La nominalisation rend l'écrit plus concis et plus soutenu. Les verbes deviennent des noms avec des terminaisons comme -tion, -ment, -ure ou -ée : \"ouvrir\" donne \"l'ouverture\", \"augmenter\" donne \"l'augmentation\", \"arriver\" donne \"l'arrivée\". Les adjectifs aussi : \"difficile\" donne \"la difficulté\". Vérifiez le genre du nouveau nom"],"tout-accord":["Tout : adjectif, pronom, adverbe","Comme adjectif, \"tout\" s'accorde avec le nom : \"tous les magasins\", \"toutes les fenêtres\". Comme adverbe au sens de \"tout à fait\", il est invariable, sauf devant un adjectif féminin commençant par une consonne : \"elle est tout étonnée\" mais \"elles sont toutes timides\""],"prepositions-apres-verbes":["Prépositions après les verbes","Certains verbes se construisent avec une préposition fixe, qui peut changer le sens. \"Penser à\" signifie avoir en tête : \"Je pense à mes vacances\" ; \"penser de\" demande un avis : \"Que penses-tu de ce film ?\". Apprenez des paires comme \"s'habituer à\" et \"se méfier de\" en bloc"],"infinitif-passe":["L'infinitif passé","\"Après\" + \"avoir\" ou \"être\" + participe passé indique qu'une action s'est passée avant l'action principale : \"Après avoir écrit la lettre, il l'a postée\". Les deux actions doivent avoir le même sujet. Les verbes de mouvement et les verbes pronominaux prennent \"être\" et s'accordent : \"Après être rentrée\", \"Après nous être reposés\""],"a-regard-pronoms-lequel":["Lequel interrogatif","\"Lequel\" demande un choix parmi des éléments connus et s'accorde avec eux : \"Lequel de ces chemins ?\", \"Laquelle de tes amies ?\". Avec \"à\" ou \"de\", il se contracte : \"Auquel de ces clients as-tu téléphoné ?\", \"Duquel parles-tu ?\". N'employez \"quel\" que juste devant un nom"]};
